465: 	}
466: 
467: 	job, err := s.Get(ctx, id)
468: 	if err != nil {
469: 		return err
470: 	}
471: 
472: 	now := time.Now().UTC()
473: 
474: 	// If max attempts reached, transition to dead
475: 	if job.Attempts >= s.maxAttempts {
476: 		if err := ValidateTransition(job.State, StateDead); err != nil {
477: 			return fmt.Errorf("transitioning job %s to dead: %w", id, err)
478: 		}
479: 		deadQuery := `
480: UPDATE jobs
481: SET state = ?, last_error = ?, lease_expires = NULL, next_attempt_at = NULL, updated_at = ?
482: WHERE id = ?;
483: `
484: 		_, err := s.db.ExecContext(ctx, deadQuery, string(StateDead), errMessage, now, id)
485: 		if err != nil {
486: 			return fmt.Errorf("marking job %s dead: %w", id, err)
487: 		}
488: 		return nil
489: 	}
490: 
491: 	// Transient failure: transition to failed with backoff
492: 	if err := ValidateTransition(job.State, StateFailed); err != nil {
493: 		return fmt.Errorf("transitioning job %s to failed: %w", id, err)
494: 	}
495: 
496: 	if backoff <= 0 {
497: 		backoff = DefaultBackoff(job.Attempts)
498: 	}
499: 	nextAttempt := now.Add(backoff)
500: 
501: 	failQuery := `
502: UPDATE jobs
503: SET state = ?, last_error = ?, lease_expires = NULL, next_attempt_at = ?, updated_at = ?
504: WHERE id = ?;
505: `
506: 	_, err = s.db.ExecContext(ctx, failQuery, string(StateFailed), errMessage, nextAttempt, now, id)
507: 	if err != nil {
508: 		return fmt.Errorf("marking job %s failed: %w", id, err)
509: 	}
510: 
511: 	return nil
512: }
