543: // ReclaimExpiredLeases scans for running jobs whose lease_expires <= now.
544: // For jobs that reached maxAttempts, they are marked dead.
545: // For jobs with remaining attempts, they are reset to queued state.
546: // Returns the count of reclaimed jobs.
547: func (s *Store) ReclaimExpiredLeases(ctx context.Context, now time.Time) (int, error) {
548: 	result, err := s.ReclaimExpiredLeasesDetailed(ctx, now)
549: 	if err != nil {
550: 		return 0, err
551: 	}
552: 	return result.Total, nil
553: }
