368: // DetectGaps inspects steps and returns any missing step index intervals.
369: func DetectGaps(steps []harness.Step) [][2]int {
370: 	if len(steps) <= 1 {
371: 		return nil
372: 	}
373: 	indices := make([]int, len(steps))
374: 	for i, s := range steps {
375: 		indices[i] = s.Index
376: 	}
377: 	sort.Ints(indices)
378: 
379: 	var gaps [][2]int
380: 	for i := 1; i < len(indices); i++ {
381: 		prev := indices[i-1]
382: 		curr := indices[i]
383: 		if curr > prev+1 {
384: 			gaps = append(gaps, [2]int{prev + 1, curr - 1})
385: 		}
386: 	}
387: 	return gaps
388: }
